/*
 * ACL_$ENTER_SUBS - Enter the subsystem a protected object names
 *
 * Original address: 0x00E46DA0 (SAU2 map: ACL_$ENTER_SUBS at E46DA0)
 * Size: 494 bytes (0x00E46DA0 .. 0x00E46F8D); its audit length cell
 * follows at 0x00E46F8E.
 * Generated by: Claude Opus 5.5
 *
 * SVC TRAP slot 0x3C (svc/svc_tables.c; DATA xref 0x00E7B556).  Frame
 * (link.w A6,-0xA4; D2-D4/A2-A5 saved; A5 = ACL_$UNWIRED_DATA 0xE7CF54):
 *   (0x08,A6) uid     -> the object UID (copied to A6-0x90)
 *   (0x0C,A6) status  (A2)
 *   (-0x28) audit_old  CURRENT_SIDS before (audit only)
 *   (-0x50) audit_new  CURRENT_SIDS after (audit only)
 *   (-0x60) proj       PROJ_LISTS[cur], updated by acl_$setids
 *   (-0x88) sids       CURRENT_SIDS[cur], updated by acl_$setids
 *   (-0x98) usp, (-0x9A) audit_flag, (-0x9E) changed
 *   D2b the result, D3b "the caller is the subsystem manager", D4b changed.
 *
 * Blocks:
 *   0x00E46DB2-0x00E46DCC  copy the UID; the longword at the user stack
 *                          pointer (the caller's return address) is the
 *                          magic value
 *   0x00E46DCE-0x00E46DFA  audit snapshot of the current SIDs
 *   0x00E46DFE-0x00E46E14  process 1 sets ACL_$UNWIRED_DATA.subs_magic and is
 *                          trusted; any other process is trusted when its
 *                          magic matches
 *   0x00E46E16-0x00E46E7E  acl_$setids on copies of the SIDs and projects
 *                          (set = trusted)
 *   0x00E46E82-0x00E46EC0  changed and trusted: a debugger that is not
 *                          superuser must itself be allowed the new SIDs,
 *                          else status_$no_right_to_perform_operation
 *   0x00E46EC2-0x00E46F1A  commit to SAVED_SIDS, CURRENT_SIDS and PROJ_LISTS
 *   0x00E46F1C-0x00E46F80  audit a change or a failure
 *
 * Quirks reproduced:
 *   - The audit record's "after" SIDs are read back from CURRENT_SIDS, so a
 *     refused change logs the unchanged SIDs.
 *   - acl_$setids' own result (its 2-byte slot) is ignored; only its
 *     `changed` byte and *status are used.
 */

#include "acl/acl_internal.h"
#include "audit/audit.h"
#include "proc1/proc1.h"
#include "proc2/proc2.h"

/* PROC1_$CURRENT of the process that defines the magic: `cmpi.w #0x1` */
#define ACL_SUBS_MANAGER_PID    1

/*
 * The audit data length, `pea (0x28,PC)` at 0x00E46F64 = 0x00E46F8E, image
 * bytes 00 24: one 36-byte SID block.
 */
static const uint16_t acl_$enter_subs_audit_len = 0x0024;

int8_t ACL_$ENTER_SUBS(uid_t *uid, status_$t *status_ret)
{
    uid_t obj;                          /* (-0x90,A6) */
    acl_sid_block_t audit_old;          /* (-0x28,A6) */
    acl_sid_block_t audit_new;          /* (-0x50,A6) */
    acl_proj_list_t proj;               /* (-0x60,A6) */
    acl_sid_block_t sids;               /* (-0x88,A6) */
    void *usp;                          /* (-0x98,A6) */
    uint16_t audit_flag;                /* (-0x9A,A6) */
    int8_t changed;                     /* (-0x9E,A6) / D4b */
    int8_t result;                      /* D2b */
    int8_t trusted;                     /* D3b */
    uint32_t magic;                     /* D0 */
    uint16_t pid;                       /* D3w */

    /* 0x00E46DAE-0x00E46DCC */
    obj = *uid;
    result = 0;
    usp = PROC1_$GET_USP();
    magic = *(const uint32_t *)usp;

    /* 0x00E46DCE-0x00E46DFA */
    if (AUDIT_$ENABLED < 0) {
        audit_old = ACL_$DATA.current_sids[PROC1_$CURRENT];
    }

    /* 0x00E46DFE-0x00E46E14 */
    if (PROC1_$CURRENT == ACL_SUBS_MANAGER_PID) {
        ACL_$UNWIRED_DATA.subs_magic = (int32_t)magic;
        trusted = (int8_t)0xFF;
    } else {
        trusted = ((uint32_t)ACL_$UNWIRED_DATA.subs_magic == magic) ? (int8_t)0xFF : 0;
    }

    /* 0x00E46E16-0x00E46E7E */
    sids = ACL_$DATA.current_sids[PROC1_$CURRENT];
    proj = ACL_$DATA.proj_lists[PROC1_$CURRENT];
    acl_$setids(&obj, trusted, &sids.user_sid, &proj.field_00, &changed,
                status_ret);

    /* 0x00E46E82-0x00E46EC0 */
    if (changed < 0 && trusted < 0) {
        pid = PROC2_$GET_DEBUGGER_PID();
        if (pid != 0 && acl_$check_suser_pid((int16_t)pid) >= 0 &&
            acl_$sids_allowed(&sids, (int16_t)pid) >= 0) {
            *status_ret = status_$no_right_to_perform_operation;
        } else {
            /* 0x00E46EC2-0x00E46F1A */
            ACL_$DATA.saved_sids[PROC1_$CURRENT] = sids;
            ACL_$DATA.current_sids[PROC1_$CURRENT] = sids;
            ACL_$DATA.proj_lists[PROC1_$CURRENT] = proj;
            result = (int8_t)0xFF;
        }
    }

    /* 0x00E46F1C-0x00E46F80 */
    if (AUDIT_$ENABLED < 0 && (changed < 0 || *status_ret != status_$ok)) {
        audit_new = ACL_$DATA.current_sids[PROC1_$CURRENT];
        if (*status_ret == status_$ok) {
            audit_flag = 0;
        } else {
            audit_flag = 1;
        }
        AUDIT_$LOG_EVENT_S(&AUDIT_$ENTER_SUBS_EU, &audit_flag, &audit_old,
                           status_ret, (char *)&audit_new,
                           &acl_$enter_subs_audit_len);
    }

    /* 0x00E46F82 */
    return result;
}
